public class SortValidator {
    public static <T extends Comparable<T>> void validateBeforeSort(T[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Array cannot be null");
        }
    }

    public static <T extends Comparable<T>> void validateAfterSort(T[] array) {
        if (array == null || array.length <= 1) {
            return;
        }

        for (int i = 0; i < array.length - 1; i++) {
            if (array[i].compareTo(array[i + 1]) > 0) {
                throw new IllegalStateException(
                        String.format("Array not properly sorted at index %d: %s > %s",
                                i, array[i], array[i + 1]));
            }
        }
    }

    public static <T> boolean isSorted(T[] array, java.util.Comparator<T> comparator) {
        if (array == null || array.length <= 1) {
            return true;
        }

        for (int i = 0; i < array.length - 1; i++) {
            if (comparator.compare(array[i], array[i + 1]) > 0) {
                return false;
            }
        }
        return true;
    }
}

